// @ts-expect-error generated by opennextjs-cloudflare build
import openNext from "./.open-next/worker.js";
import type { Env } from "./worker/env";
import { runScheduledUpdate } from "./worker/update/schedule";

export default {
  fetch: openNext.fetch.bind(openNext),
  scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    ctx.waitUntil(
      runScheduledUpdate(env).catch((err: unknown) => {
        const message = err instanceof Error ? err.message : String(err);
        console.error(JSON.stringify({ event: "scheduled_update_failed", error: message }));
      }),
    );
  },
} satisfies ExportedHandler<Env>;
